 22	/**
 23	 * Does the cohort play like a person? One line per aspect of a real player's day, measured.
 24	 *
 25	 * DEV TOOLING, read-only. Every aspect is a count over the window from the host's own tables, set
 26	 * against a floor that says how often an ordinary active player does it. A missing table is
 27	 * UNMEASURED and fails: a dead lane must never read as a quiet one. The floors below are
 28	 * measurement thresholds for this report, not module policy; nothing in the module reads them.
 29	 *
 30	 *   php Modules/AI/scripts/play-scorecard.php                    the scorecard, last 24h
 31	 *   php Modules/AI/scripts/play-scorecard.php --hours=6          a shorter window
 32	 *   php Modules/AI/scripts/play-scorecard.php --aspect=raids     exit 0 only if that aspect passes
 33	 *   php Modules/AI/scripts/play-scorecard.php --save=ECON-001    also write a snapshot (before/after)
 34	 *   php Modules/AI/scripts/play-scorecard.php --compare=FILE     print the change since a snapshot
 35	 *
 36	 * The last lines are machine-read by the harness: `PLAY: n of m aspects pass` and, when any fail,
 37	 * `PLAY: FAIL name name ...`.
 38	 */
 39	
 40	$root = dirname(__DIR__, 3);
 41	require $root.'/vendor/autoload.php';
 42	$app = require $root.'/bootstrap/app.php';
 43	$app->make(Kernel::class)->bootstrap();
 44	
 45	$options = scorecard_options(array_slice($argv, 1));
 46	$now = CarbonImmutable::now();
 47	$since = $now->subHours($options['hours']);
 48	$players = AiProfile::query()->where('enabled', true)->pluck('player_id')->map(fn ($id): int => (int) $id)->all();
 49	
 50	if ($players === []) {
 51	    echo "PLAY: no enabled AI account in this database — nothing to score\n";
 52	
 53	    exit(1);
 54	}
 55	
 56	$days = $options['hours'] / 24;
 57	$planets = DB::table('planets')->whereIn('user_id', $players)->pluck('id')->map(fn ($id): int => (int) $id)->all();
 58	$results = [];
 59	
 60	foreach (aspects() as $name => [$player, $floorPerAccountDay, $measure, $owner]) {
 61	    $count = $measure($players, $planets, $since);
 62	    $floor = (int) ceil($floorPerAccountDay * count($players) * $days);
 63	    $results[$name] = [
 64	        'count' => $count,
 65	        'floor' => $floor,
 66	        'pass' => $count !== null && $count >= $floor,
 67	        'player' => $player,
 68	        'owner' => $owner,
 69	    ];
 70	}
 71	
 72	// Breadth, not only volume: a cohort whose only fleet verb is the expedition plays one game.
 73	$fleet = array_sum(array_map(fn (string $name): int => (int) $results[$name]['count'], ['raids', 'espionage', 'transport', 'recycle', 'expeditions', 'colonisation']));
 74	$monoculture = $fleet === 0 ? 0 : (int) round(100 * (int) $results['expeditions']['count'] / $fleet);
 75	$results['fleet_breadth'] = [
 76	    'count' => $monoculture,
 77	    'floor' => 80,
 78	    'pass' => $fleet > 0 && $monoculture <= 80,
 79	    'player' => 'uses the fleet for more than one thing (expeditions are at most 80% of missions)',
 80	    'owner' => 'app/Domain/Decision/CandidateActionFactory.php',
 81	];
 82	
 83	$previous = $options['compare'] !== null && is_file($options['compare'])
 84	    ? (json_decode((string) file_get_contents($options['compare']), true)['aspects'] ?? [])
 85	    : [];
 86	
 87	printf("PLAY SCORECARD %s: %d account(s), %d planet(s), last %sh\n", DB::connection()->getDatabaseName(), count($players), count($planets), $options['hours']);
 88	
 89	foreach ($results as $name => $result) {
 90	    $value = $result['count'] === null ? 'UNMEASURED' : (string) $result['count'];
 91	    $delta = isset($previous[$name]['count']) && $result['count'] !== null
 92	        ? sprintf(' (%+d)', $result['count'] - (int) $previous[$name]['count'])
 93	        : '';
 94	    printf("  %s %-14s %10s%-8s floor %-6d %s\n", $result['pass'] ? 'PASS' : 'FAIL', $name, $value, $delta, $result['floor'], $result['player']);
 95	    if (!$result['pass']) {
 96	        printf("       owner: %s\n", $result['owner']);
 97	    }
 98	}
 99	
100	if ($options['save'] !== null) {
101	    $directory = dirname(__DIR__).'/plan/research/ogame/scorecards';
102	    @mkdir($directory, 0775, true);
103	    $path = sprintf('%s/%s-%s-%s.json', $directory, $options['save'], DB::connection()->getDatabaseName(), $now->format('Ymd-Hi'));
104	    file_put_contents($path, json_encode(['at' => $now->toIso8601String(), 'hours' => $options['hours'], 'aspects' => $results], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)."\n");
105	    echo 'snapshot: '.substr($path, strlen(dirname(__DIR__)) + 1)."\n";
106	}
107	
108	$failed = array_keys(array_filter($results, fn (array $result): bool => !$result['pass']));
109	printf("PLAY: %d of %d aspects pass\n", count($results) - count($failed), count($results));
110	echo $failed === [] ? '' : 'PLAY: FAIL '.implode(' ', $failed)."\n";
111	
112	if ($options['aspect'] !== null) {
113	    exit(($results[$options['aspect']]['pass'] ?? false) ? 0 : 1);
114	}
115	
116	exit(0);
