148	            fn (array $players, array $planets, CarbonImmutable $since): ?int => missions(ExpeditionMission::class, $players, $since),
149	            'app/Domain/Decision/QueueableExpeditionPlanner.php'],
150	        'colonisation' => ['settles new planets while slots remain', 0.05,
151	            fn (array $players, array $planets, CarbonImmutable $since): ?int => missions(ColonisationMission::class, $players, $since),
152	            'app/Domain/Decision/QueueableColonyPlanner.php'],
153	        'fleet_save' => ['saves the fleet before going offline or under attack', 0.5,
154	            fn (array $players, array $planets, CarbonImmutable $since): ?int => work_done(AiWorkKind::FleetSave, $players, $since),
155	            'app/Domain/Decision/QueueableFleetSavePlanner.php'],
156	        'social' => ['answers and starts exchanges with other players', 0.5,
157	            fn (array $players, array $planets, CarbonImmutable $since): ?int => table_count('ai_social_exchanges', 'player_id', $players, $since),
158	            'app/Actions/EvaluateAiSocialExchangeAction.php'],
159	        'chat' => ['writes to other players', 0.5,
160	            fn (array $players, array $planets, CarbonImmutable $since): ?int => model_count(ChatMessage::class, 'sender_id', $players, $since),
161	            'app/Actions/EvaluateAiSocialExchangeAction.php'],
162	        'alliance' => ['applies to, recruits for or leaves an alliance', 0.05,
163	            fn (array $players, array $planets, CarbonImmutable $since): ?int => model_count(AllianceApplication::class, 'user_id', $players, $since),
164	            'app/Actions/ReviewAiAllianceApplicationsAction.php'],
165	        'work_failures' => ['rarely has an order refused (failed work items stay under 20% of finished ones)', 0.0,
166	            fn (array $players, array $planets, CarbonImmutable $since): ?int => failure_headroom($players, $since),
167	            'app/Actions/ExecuteAiIntentAction.php'],
