171	/** Rows created in the window, or null when the host has no such table. */
172	function table_count(string $table, string $column, array $ids, CarbonImmutable $since): ?int
173	{
174	    if (!Schema::hasTable($table)) {
175	        return null;
176	    }
177	
178	    return DB::table($table)->whereIn($column, $ids)->where('created_at', '>=', $since)->count();
179	}
180	
181	/** @param class-string $model */
182	function model_count(string $model, string $column, array $ids, CarbonImmutable $since): ?int
183	{
184	    return class_exists($model) ? table_count((new $model())->getTable(), $column, $ids, $since) : null;
185	}
186	
187	/**
188	 * Missions the cohort launched, by the host's own mission type id.
189	 *
190	 * @param class-string $mission
191	 */
192	function missions(string $mission, array $players, CarbonImmutable $since): ?int
193	{
194	    if (!class_exists($mission) || !Schema::hasTable((new FleetMission())->getTable())) {
195	        return null;
196	    }
197	
198	    return FleetMission::query()->whereIn('user_id', $players)->where('mission_type', $mission::getTypeId())
199	        ->where('created_at', '>=', $since)->count();
200	}
201	
202	function work_done(AiWorkKind $kind, array $players, CarbonImmutable $since): int
203	{
204	    return DB::table('ai_work_items')->whereIn('player_id', $players)->where('kind', $kind->value)
205	        ->where('state', AiWorkState::Completed->value)->where('updated_at', '>=', $since)->count();
206	}
207	
208	/**
209	 * Percentage points left under the 20% failure ceiling, so the floor of 0 reads the same way as
210	 * every other aspect: a negative number fails.
211	 */
212	function failure_headroom(array $players, CarbonImmutable $since): int
213	{
214	    $finished = DB::table('ai_work_items')->whereIn('player_id', $players)->where('updated_at', '>=', $since)
215	        ->whereIn('state', [AiWorkState::Completed->value, AiWorkState::Failed->value])
216	        ->selectRaw('state, count(*) as total')->groupBy('state')->pluck('total', 'state');
217	    $total = (int) $finished->sum();
218	
219	    return $total === 0 ? -1 : 20 - (int) round(100 * (int) ($finished[AiWorkState::Failed->value] ?? 0) / $total);
220	}
221	
222	/** @return array{hours: float, aspect: ?string, save: ?string, compare: ?string} */
223	function scorecard_options(array $arguments): array
224	{
225	    $options = ['hours' => 24.0, 'aspect' => null, 'save' => null, 'compare' => null];
226	
227	    foreach ($arguments as $argument) {
228	        if (preg_match('/^--(hours|aspect|save|compare)=(.+)$/', $argument, $match) !== 1) {
229	            fwrite(STDERR, "unknown argument [{$argument}]\n");
230	
231	            exit(2);
232	        }
233	        // Down to six minutes: the harness reads a short window for an early pass, never for a fail.
234	        $options[$match[1]] = $match[1] === 'hours' ? max(0.1, (float) $match[2]) : $match[2];
235	    }
236	
237	    return $options;
238	}

