  1	<?php
  2	
  3	namespace Modules\AI\Actions;
  4	
  5	use Exception;
  6	use Modules\AI\Domain\Social\AllianceChoice;
  7	use Modules\AI\Models\AiProfile;
  8	use OGame\Models\Alliance;
  9	use OGame\Models\AllianceApplication;
 10	use OGame\Models\AllianceMember;
 11	use OGame\Models\Highscore;
 12	use OGame\Models\User;
 13	use OGame\Services\AllianceService;
 14	
 15	/**
 16	 * Advances cooperative alliance life: an enabled account with no alliance and no outstanding
 17	 * application applies to the alliance its tier would join. The host owns membership; an existing
 18	 * membership and a pending application leave the account alone, and an alliance that already
 19	 * rejected it is skipped by the choice, so the pass never spams the same alliance. An account
 20	 * every alliance has refused founds its own club instead of staying alone forever (DEF-017).
 21	 * A club that holds the cohort share is left by its members one at a time, which is what keeps
 22	 * the apply half above fed on a cohort that was seated once.
 23	 *
 24	 * The lane is the cohort's only source of alliance applications: a pass that finds every account
 25	 * already engaged creates none, so the leave half below keeps the lane moving at the rate the
 26	 * scorecard's alliance aspect measures. The pass itself only runs when the host's every-minute
 27	 * schedule fires, so the session path runs it too (ALLY-001).
 28	 *
 29	 * A club only receives applications while the host marks it open, so a club this action founds is
 30	 * opened for applications: a closed club is invisible to the join half above, and a cohort seated
 31	 * into closed clubs would found new ones forever while the application lane never fires (ALLY-001).
 32	 *
 33	 * A cohort where every account is seated and every club fits has no reason to move
 34	 * under the rules above, so the lane stops for good. The membership is therefore re-read each pass:
 35	 * a member whose club is no longer the club it would choose today leaves it, which is how a player
 36	 * who has outgrown or drifted from their club keeps the join half fed.
 37	 *
 38	 * A cohort whose seats the host only half wrote — a users.alliance_id with no alliance_members row,
 39	 * as seeding left grand — is neither seated nor free, so the stale link is cleared and the account
 40	 * asks on the same pass (ALLY-001).
 41	 */
 42	class AdvanceAiAllianceLifeAction
 43	{
 44	    /** The first club's tag; later founders derive their own from their name. */
 45	    private const FIRST_ALLIANCE_TAG = 'ORBITAL';
 46	
 47	    public function handle(): int
 48	    {
 49	        // An account no club fits founds its own first: a club founded after the leave half would
 50	        // be the freed account's answer to a question the join half below has not asked it yet.
 51	        $advanced = $this->foundFirstAlliance() + $this->foundWhenLockedOut();
 52	
 53	        // The leave comes before the join so the account this pass frees asks on this pass: that
 54	        // is what keeps the lane the scorecard's alliance aspect measures moving on a cohort that
 55	        // was seated once and would otherwise never ask again.
 56	        $advanced += $this->leaveOneMisfit();
 57	
 58	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
 59	            // Only an account with no seat and no outstanding request asks; a seated cohort asks
 60	            // nobody, which is why the leave half above has to free one every pass.
 61	            if ($this->alreadyEngaged($playerId)) {
 62	                continue;
 63	            }
 64	
 65	            if (app(ApplyAiAllianceAction::class)->handle($playerId)->successful) {
 66	                $advanced++;
 67	            }
 68	        }
 69	
 70	        // The leader half of the same social pass: decide pending applications (DEF-006/007)
 71	        // and answer buddy requests from known contacts (DEF-009).
 72	        $advanced += app(ReviewAiAllianceApplicationsAction::class)->handle();
 73	        $advanced += app(ReviewAiBuddyRequestsAction::class)->handle();
 74	
 75	        return $advanced;
 76	    }
 77	
 78	    /**
 79	     * A member whose club no longer fits its language and pace leaves it, one account per pass so the
 80	     * cohort spreads out the way players drift apart, not in one exodus. A founder keeps the club it
 81	     * keeps; the leaver applies to a fitting club, or founds its own, on the passes that follow.
 82	     */
 83	    private function leaveOneMisfit(): int
 84	    {
 85	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
 86	            $allianceId = User::query()->whereKey($playerId)->value('alliance_id');
 87	
 88	            if ($allianceId === null || Alliance::query()->whereKey($allianceId)->value('founder_user_id') === $playerId) {
 89	                continue;
 90	            }
 91	
 92	            if ($this->stillTheClubItWouldChoose($playerId, (int) $allianceId)) {
 93	                continue;
 94	            }
 95	
 96	            if ($this->releaseMisfit($playerId, (int) $allianceId)) {
 97	                return 1;
 98	            }
 99	        }
100	
101	        return 0;
102	    }
103	
104	    /**
105	     * Whether the club the account sits in is still the club it would choose today: the same rank
106	     * and fit rule that picks a club for an account with no seat. A club that no longer
107	     * fits its language and pace, or is outscored by another is one a player leaves, which is how a
108	     * cohort seated once — every member in a club that fits — keeps the join
109	     * half, and so the lane the scorecard's alliance aspect measures, moving (ALLY-001).
110	     */
111	    private function stillTheClubItWouldChoose(int $playerId, int $allianceId): bool
112	    {
113	        $choice = app(AllianceChoice::class)->choose($playerId);
114	
115	        // Nothing would take the account today: no rank to be judged on, or nowhere that fits. Its
116	        // seat then stands unless the club itself has stopped fitting — an account with nowhere to
117	        // go does not walk out.
118	        if ($choice === null) {
119	            return app(AllianceChoice::class)->currentClubFits($playerId);
120	        }
121	
122	        return $choice->id === $allianceId;
123	    }
124	
125	    /**
126	     * Take the misfit out of the club. The host's leaveAlliance is the normal path; a membership
127	     * the host cannot remove — a users.alliance_id written without an alliance_members row, as
128	     * seeding left them — makes it refuse, and the account would stay engaged forever while the
129	     * lane the scorecard measures creates no application. That stale link is cleared instead, so
130	     * the freed account is decided by the apply half on the next pass.
131	     */
132	    private function releaseMisfit(int $playerId, int $allianceId): bool
133	    {
134	        if (! AllianceMember::query()->where('alliance_id', $allianceId)->where('user_id', $playerId)->exists()) {
135	            $user = User::query()->find($playerId);
136	
137	            if ($user === null) {
138	                return false;
139	            }
140	
141	            $user->alliance_id = null;
142	            $user->save();
143	
144	            // The same host cooldown the leave path clears: the freed account asks on the next
145	            // pass, so the lane the alliance aspect measures keeps moving (ALLY-001).
146	            User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
147	
148	            return true;
149	        }
150	
151	        try {
152	            app(AllianceService::class)->leaveAlliance($playerId);
153	        } catch (Exception) {
154	            return false;
155	        }
156	
157	        // The host stamps a multi-day join cooldown on the account it just removed. Left in
158	        // place, the freed account can create no new application for days, and the lane the
159	        // alliance aspect measures goes quiet the moment the first club is drained (ALLY-001).
160	        // The account left to join a club that fits it; it asks on the next pass.
161	        User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
162	
163	        return true;
164	    }
165	
166	    /**
167	     * A universe with no alliance has nothing to apply to, so the first eligible
168	     * account founds one — the same first-mover move a player makes — and the
169	     * rest apply to it on later passes (DISC-012).
170	     */
171	    private function foundFirstAlliance(): int
172	    {
173	        if (Alliance::query()->exists()) {
174	            return 0;
175	        }
176	
177	        $founderId = AiProfile::query()->where('enabled', true)->orderBy('player_id')->value('player_id');
178	
179	        if ($founderId === null || $this->alreadyEngaged($founderId)) {
180	            return 0;
181	        }
182	
183	        return $this->foundAlliance($founderId, self::FIRST_ALLIANCE_TAG);
184	    }
185	
186	    /**
187	     * The second and later alliances come from the same move as the first: an account
188	     * that cannot join anywhere founds its own. A farm (no rank) is not a founder.
189	     */
190	    private function foundWhenLockedOut(): int
191	    {
192	        if (!Alliance::query()->exists()) {
193	            return 0;
194	        }
195	
196	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
197	            if ($this->alreadyEngaged($playerId)) {
198	                continue;
199	            }
200	
201	            if ((int) Highscore::query()->where('player_id', $playerId)->value('general_rank') <= 0) {
202	                continue;
203	            }
204	
205	            if (app(AllianceChoice::class)->hasOpenCandidate($playerId)) {
206	                continue;
207	            }
208	
209	            return $this->foundAlliance($playerId, $this->tagFor($playerId));
210	        }
211	
212	        return 0;
213	    }
214	
215	    /**
216	     * The tag is the founder's own name, not a module list: a club takes its founder's
217	     * identity, and the host enforces 3-8 chars and uniqueness.
218	     */
219	    private function tagFor(int $founderId): string
220	    {
221	        $username = (string) User::query()->whereKey($founderId)->value('username');
222	        $base = substr(strtoupper((string) preg_replace('/[^A-Z0-9]/', '', $username)) . 'CLUB', 0, 6);
223	
224	        foreach (['', '2', '3', '4', '5'] as $suffix) {
225	            $tag = $base . $suffix;
226	
227	            if (!Alliance::query()->where('alliance_tag', $tag)->exists()) {
228	                return $tag;
229	            }
230	        }
231	
232	        // ponytail: six candidates from one name cover a handful of founders; a
233	        // denser universe falls through to a tag createAlliance will refuse, and
234	        // the next pass retries.
235	        return $base;
236	    }
237	
238	    private function foundAlliance(int $founderId, string $tag): int
239	    {
240	        try {
241	            $alliance = app(AllianceService::class)->createAlliance($founderId, $tag, ucfirst(strtolower($tag)) . ' Pact');
242	
243	            // A club receives applications only while the host marks it open. A club this pass
244	            // founds is the cohort's own place to apply, so it is opened here: a closed club is
245	            // invisible to the join half and the application lane never fires (ALLY-001).
246	            if (! $alliance->is_open) {
247	                $alliance->is_open = true;
248	                $alliance->save();
249	            }
250	        } catch (Exception $exception) {
251	            // A cooldown or tag collision leaves the universe unchanged; the next
252	            // pass retries with the next eligible account.
253	            return 0;
254	        }
255	
256	        return 1;
257	    }
258	
259	    private function alreadyEngaged(int $playerId): bool
260	    {
261	        $user = User::query()->find($playerId);
262	
263	        if ($user === null || $user->alliance_id !== null) {
264	            return true;
265	        }
266	
267	        return AllianceApplication::query()
268	            ->where('user_id', $playerId)
269	            ->where('status', AllianceApplication::STATUS_PENDING)
270	            ->exists();
271	    }
272	}

