 3	/**
 4	 * Copy the running cohort's database into a simulation database.
 5	 *
 6	 * DEV TOOLING: reads the database the container is configured for and writes `$argv[1]` (default
 7	 * `ogamex-sim`), dropping it first. Pure SQL through PDO, so it needs no mysql client in the container.
 8	 * The copy is what `ai:sim` is allowed to move into the future; the live cohort is never touched.
 9	 *
10	 *   php Modules/AI/scripts/sim-clone.php ogamex-sim
11	 */
12	
13	$source = (string) getenv('DB_DATABASE');
14	$target = $argv[1] ?? 'ogamex-sim';
15	
16	if ($source === '' || $source === $target || !str_contains(strtolower($target), 'sim')) {
17	    fwrite(STDERR, "usage: DB_DATABASE=<cohort db> php sim-clone.php <target containing \"sim\">\n");
18	
19	    exit(2);
20	}
21	
22	$pdo = new PDO(
23	    sprintf('mysql:host=%s;port=%s', getenv('DB_HOST'), getenv('DB_PORT') ?: '3306'),
24	    (string) getenv('DB_USERNAME'),
25	    (string) getenv('DB_PASSWORD'),
26	    [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION],
27	);
28	
29	$started = microtime(true);
30	$pdo->exec("DROP DATABASE IF EXISTS `{$target}`");
31	$pdo->exec("CREATE DATABASE `{$target}` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
32	$pdo->exec('SET FOREIGN_KEY_CHECKS = 0');
33	$pdo->exec('SET UNIQUE_CHECKS = 0');
34	
35	$tables = $pdo->query(
36	    "SELECT table_name FROM information_schema.tables WHERE table_schema = '{$source}' AND table_type = 'BASE TABLE'"
37	)->fetchAll(PDO::FETCH_COLUMN);
38	
39	foreach ($tables as $table) {
40	    $pdo->exec("CREATE TABLE `{$target}`.`{$table}` LIKE `{$source}`.`{$table}`");
41	    $pdo->exec("INSERT INTO `{$target}`.`{$table}` SELECT * FROM `{$source}`.`{$table}`");
42	}
43	
44	$pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
45	printf("cloned %d table(s) %s -> %s in %.1f s\n", count($tables), $source, $target, microtime(true) - $started);

