 18	use Illuminate\Support\Facades\Schema;
 19	use Modules\AI\Domain\Decision\DefenseCompositionPlanner;
 20	use Modules\AI\Domain\Decision\DefenseNeedEvaluator;
 21	use Modules\AI\Domain\Decision\QueueableBuilding;
 22	use Modules\AI\Domain\Decision\QueueableBuildingPlanner;
 23	use Modules\AI\Domain\Decision\QueueableResearch;
 24	use Modules\AI\Domain\Decision\ReserveFloor;
 25	use Modules\AI\Domain\Lifecycle\AccountStateResolver;
 26	use Modules\AI\Domain\Perception\PlayerObservationService;
 27	use Modules\AI\Enums\AiWorkKind;
 28	use Modules\AI\Enums\AiWorkState;
 29	use Modules\AI\Models\AiProfile;
 30	use OGame\Factories\PlayerServiceFactory;
 31	use OGame\GameObjects\Models\Enums\GameObjectType;
 32	use OGame\Models\BuildingQueue;
 33	use OGame\Services\ObjectService;
 34	use OGame\Services\PlanetService;
 35	
 36	echo "\n=== cohort verification — ".now()->toDateTimeString()." ===\n";
 37	
 38	$profiles = AiProfile::query()->where('enabled', true)->get();
 39	
 40	if ($profiles->isEmpty()) {
 41	    echo "No enabled AI accounts in this universe.\n";
 42	
 43	    return;
 44	}
 45	
 46	$playerIds = $profiles->pluck('player_id')->map(fn ($id): int => (int) $id)->all();
 47	$planetIds = DB::table('planets')->whereIn('user_id', $playerIds)->pluck('id')->map(fn ($id): int => (int) $id)->all();
 48	
 49	// One aggregate per defence object for the whole cohort, rather than one per object per planet:
 50	// 10 queries instead of ~1,800 on a mature universe, and the number is the same.
 51	$defenceUnits = 0;
 52	$defenceDetail = [];
 53	foreach (ObjectService::getDefenseObjects() as $object) {
 54	    $amount = (int) DB::table('planets')->whereIn('id', $planetIds)->sum($object->machine_name);
 55	    $defenceUnits += $amount;
 56	    if ($amount > 0) {
 57	        $defenceDetail[$object->machine_name] = $amount;
 58	    }
 59	}
 60	
 61	$orders = [];
 62	$inflight = [];
 63	$missing = [];
 64	foreach (['building_queues', 'research_queues', 'unit_queues'] as $table) {
 65	    if (! Schema::hasTable($table)) {
 66	        // Loud, not zero: silently reading a wrong table name is how a busy cohort looks dead.
 67	        $missing[] = $table;
 68	        $orders[$table] = 0;
 69	        $inflight[$table] = 0;
 70	
 71	        continue;
 72	    }
 73	    // Rows in flight are a bad activity measure: these universes run fast enough to drain a queue
 74	    // in seconds, so a healthy cohort reads as zero. Orders *placed* in the last ten minutes is the
 75	    // number that says whether it is playing.
 76	    $orders[$table] = DB::table($table)
 77	        ->whereIn('planet_id', $planetIds)
 78	        ->where('created_at', '>=', now()->subMinutes(10))
 79	        ->count();
 80	    $inflight[$table] = DB::table($table)
 81	        ->whereIn('planet_id', $planetIds)
 82	        ->where('processed', 0)
 83	        ->count();
 84	}
 85	
 86	if ($missing !== []) {
 87	    echo 'MISSING TABLES: '.implode(', ', $missing)." — the counts below are meaningless\n";
 88	}
 89	
 90	$states = DB::table('ai_work_items')
 91	    ->whereIn('player_id', $playerIds)
 92	    ->selectRaw('state, count(*) as total')
 93	    ->groupBy('state')
 94	    ->pluck('total', 'state')
 95	    ->all();
 96	
 97	printf(
 98	    "profiles: %d   planets: %d   defence units: %s\n"
 99	    ."orders last 10 min: building %d, research %d, units %d   (in flight: %d/%d/%d)\n"
100	    ."receipts: %s   decisions: %s   work items by state: %s\n",
101	    $profiles->count(),
102	    count($planetIds),
103	    number_format($defenceUnits),
104	    $orders['building_queues'],
105	    $orders['research_queues'],
106	    $orders['unit_queues'],
107	    $inflight['building_queues'],
108	    $inflight['research_queues'],
109	    $inflight['unit_queues'],
110	    number_format(DB::table('ai_action_receipts')->whereIn('player_id', $playerIds)->count()),
111	    number_format(DB::table('ai_decision_traces')->whereIn('player_id', $playerIds)->count()),
112	    json_encode($states)
113	);
114	
115	if ($defenceDetail !== []) {
116	    echo 'defence held: '.json_encode($defenceDetail)."\n";
117	}
118	
119	// Research is the other half of a real account: a cohort that never researches cannot colonise,
120	// cannot expedition and cannot fleet-crash, which is the difference between a player and a miner.
121	// Astrophysics is the usual gate — every later account feature hangs off it.
122	if (Schema::hasTable('users_tech')) {
123	    $astrophysics = (int) DB::table('users_tech')->whereIn('user_id', $playerIds)->sum('astrophysics');
124	    $atZero = DB::table('users_tech')->whereIn('user_id', $playerIds)->where('astrophysics', 0)->count();
125	
126	    printf(
127	        "astrophysics: %d level(s) across the cohort, %d of %d accounts still at 0\n",
128	        $astrophysics,
129	        $atZero,
130	        count($playerIds)
131	    );
132	}
133	
134	// Research health. A cancelled row is a decision the host refused, and nothing ever marks a
135	// cancelled row processed, so a lifetime total cannot say whether it is happening now: read the
136	// newest rows instead.
137	if (Schema::hasTable('research_queues')) {
138	    $recent = DB::table('research_queues')->orderByDesc('id')->limit(300)->get();
139	
140	    printf(
141	        "research (newest 300 rows): %d cancelled, %d completed, %d waiting\n",
142	        $recent->where('canceled', 1)->count(),
143	        $recent->where('processed', 1)->count(),
144	        $recent->where('canceled', 0)->where('processed', 0)->count()
145	    );
