147	    // A rolling window, because the newest-300 view mixes whatever a fix changed with what came
148	    // before it. This is the number that says whether the cohort still cancels its own research.
149	    $windowStart = now()->subMinutes(20);
150	    $window = DB::table('research_queues')->where('created_at', '>=', $windowStart);
151	
152	    printf(
153	        "research (last 20 min): %d rows, %d cancelled\n",
154	        (clone $window)->count(),
155	        (clone $window)->where('canceled', 1)->count()
156	    );
157	
158	    $sample = DB::table('research_queues')->orderByDesc('id')->where('canceled', 1)->first();
159	    if ($sample !== null) {
160	        printf(
161	            "  newest cancelled: planet %d, object %d, target level %d, cost %d, created %s\n",
162	            $sample->planet_id,
163	            $sample->object_id,
164	            $sample->object_level_target,
165	            $sample->metal,
166	            $sample->created_at
167	        );
168	    }
