171	printf(
172	    "due now: %s   leased: %s   pending: %s\n",
173	    // Only work that is still waiting: without the state filter this counts the million rows that
174	    // are already completed and past their due time, so it read "1,089,229 due" about a cohort with
175	    // fifty items outstanding and made a healthy queue look like a backlog (found 30 Sep 2026).
176	    number_format(DB::table('ai_work_items')->whereIn('player_id', $playerIds)
177	        ->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value])
178	        ->where('due_at', '<=', now())->count()),
179	    number_format($states[2] ?? 0),
180	    number_format($states[1] ?? 0)
181	);
