183	// Quality, not liveness. Everything above proves the accounts *play*; none of it can tell whether
184	// they play *well*, which is how a cohort spent a whole session walling one planet and leaving 125
185	// naked while every counter above read healthy (found 29 Sep 2026). These are the three shapes the
186	// damage took, stated as thresholds so a human reading the log sees the defect named. They are
187	// measurement thresholds for this log, not module policy: nothing in the module reads them.
188	//
189	//   NAKED_BESIDE_WALLED  an account with a planet at zero defence while a sibling holds a real wall
190	//   WALL_CEILING         one planet holding more defence units than any single planet needs
191	//   ALLIANCE_SHARE       one alliance holding more than this share of the AI accounts
192	//   IDLE_QUEUES          an account that played in the last hour with most buildable planets' queues empty
193	//   UNIVERSE_SPEED       the economy or a fleet speed above the 1000x grand-test protocol
194	$nakedBesideWalled = [];
195	$overCeiling = [];
196	$WALL_CEILING = 20_000;
197	$ALLIANCE_SHARE = 0.6;
198	
199	$defenceSum = collect(ObjectService::getDefenseObjects())
200	    ->map(fn ($object): string => '`'.$object->machine_name.'`')
201	    ->implode(' + ');
202	
203	// Moons are left out when the host says which rows are moons: a moon without defence is ordinary,
204	// and counting it would make this invariant cry wolf until nobody reads it.
205	$planetQuery = DB::table('planets')->whereIn('user_id', $playerIds);
206	// A colony founded this hour has no shipyard and a few hundred metal: a player builds mines first and
207	// walls it once the yard exists, so a planet is only counted bare after that lead time.
208	$planetQuery->where('created_at', '<=', now()->subHour());
209	if (Schema::hasColumn('planets', 'planet_type')) {
210	    $planetQuery->where('planet_type', '!=', 3);
211	}
212	
213	$byAccount = [];
214	foreach ($planetQuery->selectRaw("user_id, id, ($defenceSum) as defence")->get() as $row) {
215	    $byAccount[(int) $row->user_id][] = ['id' => (int) $row->id, 'defence' => (int) $row->defence];
216	}
217	
218	foreach ($byAccount as $accountId => $planets) {
219	    $walls = array_column($planets, 'defence');
220	    $strongest = max($walls);
221	    $naked = count(array_filter($walls, fn (int $units): bool => $units === 0));
222	
223	    if ($naked > 0 && $strongest > 1000) {
224	        $nakedBesideWalled[] = sprintf('player %d: %d planet(s) at zero defence while one holds %s units', $accountId, $naked, number_format($strongest));
225	    }
226	
227	    foreach ($planets as $planet) {
228	        if ($planet['defence'] <= $WALL_CEILING) {
229	            continue;
230	        }
231	        $overCeiling[] = sprintf('planet %d holds %s defence units', $planet['id'], number_format($planet['defence']));
232	    }
233	}
234	
235	$allianceShare = [];
236	if (Schema::hasColumn('users', 'alliance_id')) {
237	    $members = DB::table('users')->whereIn('id', $playerIds)->whereNotNull('alliance_id')
238	        ->selectRaw('alliance_id, count(*) as members')->groupBy('alliance_id')->pluck('members', 'alliance_id');
239	
240	    foreach ($members as $allianceId => $count) {
241	        $share = $count / count($playerIds);
242	        if ($share > $ALLIANCE_SHARE) {
243	            $allianceShare[] = sprintf('alliance %s holds %d of %d AI accounts (%.0f%%)', $allianceId, $count, count($playerIds), $share * 100);
244	        }
245	    }
246	}
