248	// A player who logs in fills every planet's build queue where something can be built. IDLE_QUEUES
249	// counts only the planets the planner has a step for and that have no building in progress: a planet
250	// whose every candidate the host refuses (no free field, lab busy, price plus reserve) is SATURATED,
251	// which is information about the universe, not a defect of the account, and is printed below for the
252	// accounts the stored state could not already clear.
253	$IDLE_SHARE = 0.5;
254	$idleQueues = [];
255	$saturated = [];
256	$playedThisHour = DB::table('ai_work_items')->whereIn('player_id', $playerIds)
257	    ->where('kind', AiWorkKind::RunSession->value)->where('updated_at', '>=', now()->subHour())
258	    ->distinct()->pluck('player_id')->map(fn ($id): int => (int) $id)->all();
259	$busyPlanets = BuildingQueue::query()->where('processed', 0)->where('time_end', '>', time())
260	    ->distinct()->pluck('planet_id')->map(fn ($id): int => (int) $id)->all();
261	
262	// A planet whose build order is already queued is being filled: the session that placed it is done, the
263	// order runs a few minutes later, and at 1000x the planet reads idle in between.
264	$ordered = [];
265	foreach (DB::table('ai_work_items')->whereIn('player_id', $playerIds)->where('kind', AiWorkKind::BuildFirstBuilding->value)
266	    ->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value, AiWorkState::Leased->value])->pluck('payload') as $payload) {
267	    $ordered[] = (int) (json_decode((string) $payload, true)['planet_id'] ?? 0);
268	}
269	
270	$buildingPlanner = app(QueueableBuildingPlanner::class);
271	
272	foreach ($playedThisHour as $accountId) {
273	    $ownPlanets = array_column($byAccount[$accountId] ?? [], 'id');
274	    if ($ownPlanets === []) {
275	        continue;
276	    }
277	
278	    // At 1000x a build ends in minutes, so a planet read between its last build ending and the
279	    // account's next turn is waiting, not neglected. Idle means the account finished a session
280	    // after the planet's last build ended and the planet still has a legal step and no build.
281	    $lastSession = (int) strtotime((string) DB::table('ai_work_items')->where('player_id', $accountId)
282	        ->where('kind', AiWorkKind::RunSession->value)->where('state', AiWorkState::Completed->value)->max('updated_at'));
283	    // A build ordered around the last session is that session's work: its orders run minutes after it
284	    // and finish within seconds, so the planet is idle only when a session passed with no order for it.
285	    $lastBuildEnd = BuildingQueue::query()->whereIn('planet_id', $ownPlanets)->where('canceled', 0)
286	        ->groupBy('planet_id')->selectRaw('planet_id, max(greatest(time_end, time_start + 300)) as ended')->pluck('ended', 'planet_id');
287	    // The planner costs about a second per account and is the whole price of this read, so it is asked
288	    // only about an account the stored state cannot already clear: more than the idle share of its
289	    // planets must be free of a build, an order and a newer session than their last build.
290	    $waiting = array_filter($ownPlanets, static fn (int $id): bool => !in_array($id, $busyPlanets, true)
291	        && !in_array($id, $ordered, true)
292	        && $lastSession > (int) ($lastBuildEnd[$id] ?? 0));
293	    if (count($waiting) / count($ownPlanets) <= $IDLE_SHARE) {
294	        continue;
295	    }
296	
297	    $player = app(PlayerServiceFactory::class)->make($accountId, true);
298	    // "Buildable" means the building planner has a *building* step for the planet. A step that is a
299	    // technology belongs to the account's one lab, not to this planet's build queue: the account is
300	    // researching, which is play, and the lab step carries its planet's id, so an account researching
301	    // read as buildable with an empty build queue on every pass.
302	    $planned = array_values(array_map(
303	        static fn ($step): int => $step->planetId,
304	        array_filter($buildingPlanner->steps($accountId, $player), static fn ($step): bool => $step instanceof QueueableBuilding),
305	    ));
306	    $idle = array_filter($waiting, static fn (int $id): bool => in_array($id, $planned, true));
307	
308	    if (count($idle) / count($ownPlanets) > $IDLE_SHARE) {
309	        $idleQueues[] = sprintf('player %d played this hour with %d of %d planets buildable and idle', $accountId, count($idle), count($ownPlanets));
310	    }
311	
312	    $reasons = [];
313	    $profile = AiProfile::query()->where('player_id', $accountId)->first();
314	    foreach ($player->planets->all() as $planet) {
315	        $id = $planet->getPlanetId();
316	        if (!in_array($id, $ownPlanets, true) || in_array($id, $planned, true) || in_array($id, $busyPlanets, true)) {
317	            continue;
318	        }
319	        $reason = saturation_reason($buildingPlanner, $profile, $planet);
320	        $reasons[$reason] = ($reasons[$reason] ?? 0) + 1;
321	    }
322	    if ($reasons !== []) {
323	        $saturated[] = sprintf('player %d: %d planet(s) with every candidate refused (%s)', $accountId, array_sum($reasons), implode(', ', array_map(
324	            static fn (string $reason, int $count): string => "{$reason}: {$count}",
325	            array_keys($reasons),
326	            $reasons,
327	        )));
328	    }
329	}
