331	/**
332	 * Why a planet that nothing could be queued on is not building: the refusal of its first candidate,
333	 * asked of the planner's own gates. A technology among the candidates means the lab is taken.
334	 */
335	function saturation_reason(QueueableBuildingPlanner $planner, AiProfile $profile, PlanetService $planet): string
336	{
337	    foreach ($planner->passes($profile) as $candidates) {
338	        foreach ($candidates($planet) as $candidate) {
339	            if (ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research) {
340	                return 'lab busy';
341	            }
342	
343	            return $planner->refusal($planet, $candidate) ?? 'queueable';
344	        }
345	    }
346	
347	    return 'no candidate';
348	}
349	
350	// The grand-test protocol runs the economy at 1000x (local-docker-dev/capacity-run.sh). A cohort run
351	// faster than that fills every field and banks billions in a day (90,000x did, on 1 Oct 2026), and
352	// every human-timescale measure stops meaning anything; reseed instead of raising it.
353	$UNIVERSE_SPEED = 1000;
354	$tooFast = [];
355	if (Schema::hasTable('settings')) {
356	    $speeds = DB::table('settings')->where('key', 'economy_speed')->orWhere('key', 'like', 'fleet_speed%')->pluck('value', 'key');
357	    foreach ($speeds as $name => $value) {
358	        if ((float) $value > $UNIVERSE_SPEED) {
359	            $tooFast[] = sprintf('%s is %s, above the %dx grand-test protocol', $name, $value, $UNIVERSE_SPEED);
360	        }
361	    }
362	}
363	
364	// Authenticity (AUTH-001): what a neighbour or an operator could observe about the cohort as a
365	// crowd, from account-authenticity.md. Each signature is read from state the host or the module
366	// already keeps, over the last seven days. They are measurement thresholds for this log, like the
367	// quality ones above, and a failing signature is raised like any other invariant.
368	//
369	//   AUTH_UPTIME      an account whose finished sessions cover this many hours of the day (the host's own
370	//                    round-the-clock flag is 18) never sleeps
371	//   AUTH_REPETITION  an account whose most common five-action run is this share of its recent actions
372	//   AUTH_SAVE        a cohort that has saved this many fleets and never once lost one
373	//   AUTH_CONTACT     a cohort in which fewer than this share of accounts ever wrote to another player
374	//   AUTH_GROWTH      an account whose public score is this many times the cohort median, or a tenth of it
375	$AUTH_UPTIME_HOURS = 18;
376	$AUTH_REPEAT_SHARE = 0.5;
377	$AUTH_SAVES_WITHOUT_LOSS = 20;
378	$AUTH_CONTACT_SHARE = 0.25;
379	$AUTH_GROWTH_RATIO = 10;
380	$week = now()->subDays(7);
381	
382	$authUptime = [];
383	$sessions = DB::table('ai_work_items')->whereIn('player_id', $playerIds)->where('kind', AiWorkKind::RunSession->value)
384	    ->where('state', AiWorkState::Completed->value)->where('updated_at', '>=', $week)
385	    ->selectRaw('player_id, count(distinct hour(updated_at)) as hours')->groupBy('player_id')->get();
386	foreach ($sessions as $row) {
387	    if ((int) $row->hours >= $AUTH_UPTIME_HOURS) {
388	        $authUptime[] = sprintf('player %d is active in %d of 24 hours of the day', $row->player_id, $row->hours);
389	    }
390	}
391	
392	$authRepetition = [];
393	foreach ($playerIds as $accountId) {
394	    $kinds = DB::table('ai_work_items')->where('player_id', $accountId)->where('kind', '!=', AiWorkKind::RunSession->value)
395	        ->orderByDesc('id')->limit(300)->pluck('kind')->all();
396	    if (count($kinds) < 50) {
397	        continue;
398	    }
399	    $grams = [];
400	    for ($i = 0; $i + 5 <= count($kinds); $i++) {
401	        $gram = implode(',', array_slice($kinds, $i, 5));
402	        $grams[$gram] = ($grams[$gram] ?? 0) + 1;
403	    }
404	    $share = max($grams) / array_sum($grams);
405	    if ($share > $AUTH_REPEAT_SHARE) {
406	        $authRepetition[] = sprintf('player %d repeats one five-action run for %.0f%% of its recent actions', $accountId, $share * 100);
407	    }
408	}
409	
410	$authSave = [];
411	$saves = DB::table('ai_work_items')->whereIn('player_id', $playerIds)->where('kind', AiWorkKind::FleetSave->value)->where('updated_at', '>=', $week);
412	$savesTotal = (clone $saves)->count();
413	// A save is lost when its work failed or when the account chose not to take it (the stop counter).
414	$savesLost = (int) DB::table('ai_stop_counters')->where('reason', 'save_lost')->where('observed_on', '>=', $week->toDateString())->sum('occurrences');
415	$savesFailed = (clone $saves)->where('state', AiWorkState::Failed->value)->count() + $savesLost;
416	$savesTotal += $savesLost;
417	if ($savesTotal >= $AUTH_SAVES_WITHOUT_LOSS && $savesFailed === 0) {
418	    $authSave[] = sprintf('%d fleet saves in a week and none ever failed: a human loses one now and then', $savesTotal);
419	}
420	
421	$authContact = [];
422	if (Schema::hasTable('chat_messages')) {
423	    $talkers = DB::table('chat_messages')->whereIn('sender_id', $playerIds)->where('created_at', '>=', $week)
424	        ->whereColumn('recipient_id', '!=', 'sender_id')->distinct()->count('sender_id');
425	    if ($talkers / count($playerIds) < $AUTH_CONTACT_SHARE) {
426	        $authContact[] = sprintf('only %d of %d accounts wrote to another player this week', $talkers, count($playerIds));
427	    }
428	}
429	
430	$authGrowth = [];
431	// Growth is compared among accounts that have played for days: an account seeded this hour has a
432	// score of nothing, and measuring it against its elders reads a young cohort as an abnormal one.
433	$seasoned = DB::table('ai_work_items')->whereIn('player_id', $playerIds)->groupBy('player_id')
434	    ->havingRaw('min(created_at) < ?', [now()->subDays(3)])->pluck('player_id')->all();
435	$scores = DB::table('highscores')->whereIn('player_id', $seasoned)->pluck('general', 'player_id')->map(fn ($v): float => (float) $v)->all();
436	if (count($scores) >= 5) {
437	    $sorted = array_values($scores);
438	    sort($sorted);
439	    $median = $sorted[intdiv(count($sorted), 2)];
440	    foreach ($scores as $accountId => $score) {
441	        if ($median > 0 && ($score > $median * $AUTH_GROWTH_RATIO || $score < $median / $AUTH_GROWTH_RATIO)) {
442	            $authGrowth[] = sprintf('player %d scores %s against a cohort median of %s', $accountId, number_format($score), number_format($median));
443	        }
444	    }
445	}
