447	// Named invariants, one line per violation, and a machine-readable verdict at the end. The harness
448	// reads that line to raise a task for anything the cohorts fail, so a repeated "QUALITY: FAIL" is not
449	// a dead end someone has to notice by eye.
450	// What an administrator sees in the universe: players fight each other and moons appear. A day of raids
451	// that only pillage empty planets has no combat rounds, no debris and no moons, which reads as a dead
452	// universe however many missions ran.
453	//   LIFE_FIGHTS  at least this share of the day's battles has a defender and combat rounds
454	//   LIFE_MOONS   a universe with this many battles in a day and no moon at all
455	$LIFE_FIGHT_SHARE = 0.2;
456	$LIFE_MOON_BATTLES = 100;
457	$lifeFights = [];
458	$lifeMoons = [];
459	$dayBattles = DB::table('battle_reports')->where('created_at', '>=', now()->subDay())->get(['rounds']);
460	if ($dayBattles->count() >= $LIFE_MOON_BATTLES) {
461	    $fought = $dayBattles->filter(fn ($row): bool => count(json_decode((string) $row->rounds, true) ?: []) > 0)->count();
462	    if ($fought / $dayBattles->count() < $LIFE_FIGHT_SHARE) {
463	        $lifeFights[] = sprintf('%d of %d battles today had combat rounds (%.0f%%): the raids pillage empty planets instead of fighting', $fought, $dayBattles->count(), 100 * $fought / $dayBattles->count());
464	    }
465	    if (DB::table('planets')->where('planet_type', 3)->count() === 0) {
466	        $lifeMoons[] = sprintf('%d battles today and not one moon in the universe', $dayBattles->count());
467	    }
468	}
