470	//   LIFE_CAPITAL  under a tenth of the accounts own a military hull dearer than the median military hull: the host's own
471	//                 catalogue says which that is, so a mod-added capital ship counts with no edit here
472	$lifeCapital = [];
473	$military = collect(ObjectService::getMilitaryShipObjects())->filter(fn ($ship): bool => $ship->machine_name !== 'espionage_probe');
474	if ($military->count() >= 3) {
475	    $priceOf = fn ($ship): float => (float) ($ship->price->resources->metal->get() + $ship->price->resources->crystal->get() + $ship->price->resources->deuterium->get());
476	    $prices = $military->map($priceOf)->sort()->values();
477	    $median = $prices[intdiv($prices->count(), 2)];
478	    $capital = $military->filter(fn ($ship): bool => $priceOf($ship) > $median)->map(fn ($ship): string => '`'.$ship->machine_name.'`');
479	    $owners = DB::table('planets')->whereIn('user_id', $playerIds)->whereRaw($capital->map(fn (string $column): string => "$column > 0")->implode(' or '))->distinct()->count('user_id');
480	    if ($owners / count($playerIds) < 0.1) {
481	        $lifeCapital[] = sprintf('%d of %d accounts own a military hull dearer than the median (%s): there is no war fleet', $owners, count($playerIds), $capital->implode(', '));
482	    }
483	}
484	
485	$invariants = [
486	    'LIFE_CAPITAL' => $lifeCapital,
487	    'LIFE_FIGHTS' => $lifeFights,
488	    'LIFE_MOONS' => $lifeMoons,
489	    'NAKED_BESIDE_WALLED' => $nakedBesideWalled,
490	    'WALL_CEILING' => $overCeiling,
491	    'ALLIANCE_SHARE' => $allianceShare,
492	    'IDLE_QUEUES' => $idleQueues,
493	    'UNIVERSE_SPEED' => $tooFast,
494	    'AUTH_UPTIME' => $authUptime,
495	    'AUTH_REPETITION' => $authRepetition,
496	    'AUTH_SAVE' => $authSave,
497	    'AUTH_CONTACT' => $authContact,
498	    'AUTH_GROWTH' => $authGrowth,
499	];
500	
501	$fired = array_keys(array_filter($invariants, static fn (array $rows): bool => $rows !== []));
502	$total = array_sum(array_map('count', $invariants));
503	
504	echo "\nQUALITY: ".($total === 0
505	    ? count($invariants).' of '.count($invariants).' invariants honoured'
506	    : $total.' violation(s) across '.count($fired).' invariant(s)')."\n";
507	
508	foreach ($invariants as $name => $rows) {
509	    foreach ($rows as $row) {
510	        echo '  ! ['.$name.'] '.$row."\n";
511	    }
512	}
513	
514	echo $fired === [] ? '' : 'QUALITY: FAIL '.implode(' ', $fired)."\n";
515	
516	foreach (array_filter(array_keys($invariants), fn (string $name): bool => str_starts_with($name, 'AUTH_')) as $name) {
517	    echo 'AUTHENTICITY: '.($invariants[$name] === [] ? 'PASS' : 'FAIL').' '.$name."\n";
518	}
519	
520	// Information, not a violation: planets the planner had nothing to queue on because the host refused
521	// every candidate. When this covers most planets of most accounts the run is over (reseed).
522	foreach ($saturated as $row) {
523	    echo '  SATURATED '.$row."\n";
524	}
