526	// The expensive part, only for the accounts asked for. This is what answers "why is this account
527	// doing nothing": the account's state, the capabilities the perception publishes, the step the
528	// chain wants next, and the wall the doctrine would build.
529	require_once __DIR__.'/economy-explain.php';
530	
531	foreach (($argv ?? []) as $playerId) {
532	    $playerId = (int) $playerId;
533	    foreach (explain_economy($playerId) as $line) {
534	        echo '  economy '.$line."\n";
535	    }
536	    $player = app(PlayerServiceFactory::class)->make($playerId, true);
537	    $observation = app(PlayerObservationService::class)->ownedState($playerId);
538	    $published = array_keys(array_filter($observation['available_actions']));
539	
540	    printf(
541	        "\nplayer %d  state %s  published %s  planets %d\n",
542	        $playerId,
543	        app(AccountStateResolver::class)->resolve($playerId)->name,
544	        $published === [] ? 'NOTHING' : implode(', ', $published),
545	        count($player->planets->all())
546	    );
547	
548	    foreach (array_slice($player->planets->all(), 0, 3) as $planet) {
549	        $planet->updateResources(false);
550	        $planet->updateResourceProductionStats(false);
551	        $planet->updateResourceStorageStats(false);
552	
553	        $resources = $planet->getResources();
554	        $floor = app(ReserveFloor::class)->floor($planet, ReserveFloor::ECONOMY_HOURS);
555	        $step = app(QueueableBuildingPlanner::class)->plan($playerId, $player);
556	        $need = app(DefenseNeedEvaluator::class)->evaluate($player, $planet);
557	        $wall = app(DefenseCompositionPlanner::class)->plan($player, $planet, $need);
558	
559	        $next = match (true) {
560	            $step instanceof QueueableBuilding => ObjectService::getObjectById($step->buildingId)->machine_name.' ('.$step->reason.')',
561	            $step instanceof QueueableResearch => ObjectService::getObjectById($step->researchId)->machine_name.' ('.$step->reason.')',
562	            default => 'NONE — only DoNothing offered',
563	        };
564	
565	        $built = 0;
566	        foreach (ObjectService::getDefenseObjects() as $object) {
567	            $built += $planet->getObjectAmount($object->machine_name);
568	        }
