 3	namespace Modules\AI\Domain\Decision\Policies;
 4	
 5	use Modules\AI\Enums\AiArchetype;
 6	use Modules\AI\Enums\AiCandidateActionType;
 7	use RuntimeException;
 8	use Symfony\Component\Yaml\Yaml;
 9	
10	/**
11	 * A legal intent set plus the taste among it, read per archetype from one data file.
12	 *
13	 * The weights live in `resources/behavior/archetype-preferences.yaml` only: an archetype states
14	 * how readily its account takes each errand, so one tuning pass moves the whole dimension there
15	 * and no policy class restates a number (PERS-008).
16	 */
17	abstract class ConfiguredArchetypePolicy implements ArchetypePolicy
18	{
19	    /** Module root relative, so the taste of every archetype is read by name. */
20	    private const PREFERENCES_FILE = '/resources/behavior/archetype-preferences.yaml';
21	
22	    /** @var array<int, float> action value => weight */
23	    protected array $preferences = [];
24	
25	    /** @var array<int, bool> action value => legality, when a policy marks an intent illegal */
26	    protected array $allowed = [];
27	
28	    public function __construct()
29	    {
30	        $this->preferences = self::table()[strtolower($this->archetype()->name)] ?? [];
31	    }
32	
33	    public function allows(AiCandidateActionType $action): bool
34	    {
35	        return $this->allowed[$action->value] ?? true;
36	    }
37	
38	    public function preference(AiCandidateActionType $action): float
39	    {
40	        return $this->preferences[$action->value] ?? 0.0;
41	    }
42	
43	    /**
44	     * The file's sections keyed by archetype name, each action name resolved to its enum value:
45	     * a typo in the file is an error rather than a taste that quietly applies to nobody.
46	     *
47	     * @return array<string, array<int, float>>
48	     */
49	    private static function table(): array
50	    {
51	        static $table = null;
52	
53	        if ($table !== null) {
54	            return $table;
55	        }
56	
57	        $path = dirname(__DIR__, 4) . self::PREFERENCES_FILE;
58	        $parsed = is_file($path) ? Yaml::parseFile($path) : null;
59	        $table = [];
60	
61	        foreach (is_array($parsed) ? $parsed : [] as $archetype => $weights) {
62	            $row = [];
63	
64	            foreach (is_array($weights) ? $weights : [] as $action => $weight) {
65	                $row[self::intent((string) $action)->value] = (float) $weight;
66	            }
67	
68	            $table[strtolower((string) $archetype)] = $row;
69	        }
70	
71	        return $table;
72	    }
73	
74	    private static function intent(string $name): AiCandidateActionType
75	    {
76	        // Keys are written snake_case (`fleet_save`), enum cases are not (`FleetSave`).
77	        $normalised = strtolower(str_replace('_', '', $name));
78	
79	        foreach (AiCandidateActionType::cases() as $case) {
80	            if (strtolower($case->name) === $normalised) {
81	                return $case;
82	            }
83	        }
84	
85	        throw app()->makeWith(RuntimeException::class, [
86	            'message' => 'archetype-preferences: "' . $name . '" is not an intent (' . basename(self::PREFERENCES_FILE) . ').',
87	        ]);
88	    }
89	
90	    abstract public function archetype(): AiArchetype;
91	}

