 4	
 5	use Illuminate\Console\Attributes\Description;
 6	use Illuminate\Console\Attributes\Signature;
 7	use Illuminate\Console\Command;
 8	use Modules\AI\Actions\SeedAiTestUniverseAction;
 9	use OGame\Models\ChatMessage;
10	use OGame\Models\User;
11	
12	/**
13	 * Seeds the 10-account grand-test universe.
14	 *
15	 * Every account starts exactly where a normal player starts: zero buildings, zero research,
16	 * default resources, one Homeworld — the same registration path a human takes. Nothing is gifted;
17	 * every building the account ever shows is one it queued through its own planner on its own
18	 * schedule. The only thing this command adds beyond registration is a couple of inbound greetings.
19	 */
20	#[Description('Seed the grand-test universe of fresh accounts. Refuses production.')]
21	#[Signature('ai:seed-grand-test
22	            {--players=10 : Number of AI accounts}
23	            {--confirm : Required confirmation}')]
24	class SeedGrandTest extends Command
25	{
26	    public function handle(): int
27	    {
28	        if ($this->getLaravel()->environment('production')) {
29	            $this->error('Refusing to seed synthetic accounts in production.');
30	
31	            return self::FAILURE;
32	        }
33	
34	        if (!$this->option('confirm')) {
35	            $this->error('This creates AI accounts. Re-run with --confirm.');
36	
37	            return self::FAILURE;
38	        }
39	
40	        $players = max(1, (int) $this->option('players'));
41	
42	        $seeded = app(SeedAiTestUniverseAction::class)->handle($players);
43	        $aiIds = array_map(static fn (array $account): int => $account['player_id'], $seeded);
44	
45	        $rows = [];
46	
47	        foreach ($seeded as $index => $account) {
48	            $rows[] = [$index + 1, $account['archetype'], $account['player_id'], $account['created'] ? 'created' : 'already seeded'];
49	        }
50	
51	        $this->seedSocialMessages($seeded, $aiIds);
52	
53	        $this->newLine();
54	        $this->table(['#', 'Archetype', 'Player', 'Status'], $rows);
55	
56	        return self::SUCCESS;
57	    }
58	
59	    /**
60	     * A human neighbour greets two accounts. This is an external event a fresh player can receive
61	     * on day one, not a head start: the account still owns nothing and must answer from its own
62	     * authored replies. The conversation path is what this exercises.
63	     *
64	     * @param list<array{player_id:int, archetype:string, created:bool}> $seeded
65	     * @param list<int> $aiIds
66	     */
67	    private function seedSocialMessages(array $seeded, array $aiIds): void
68	    {
69	        $human = User::query()->whereNotIn('id', $aiIds)->first();
70	        if ($human === null) {
71	            return;
72	        }
73	
74	        foreach (array_slice($seeded, 0, 2) as $account) {
75	            ChatMessage::query()->create([
76	                'sender_id' => $human->id,
77	                'recipient_id' => $account['player_id'],
78	                'message' => 'Hello neighbour — good luck out there.',
79	            ]);
80	        }
81	    }
82	}

